def shortest_path(graph: dict, start, end) -> tuple[float, list] | None:
    if start == end:
        return (0.0, [start])

    # Priority queue: (distance, current_node, path)
    pq = [(0.0, start, [start])]
    visited = set()

    while pq:
        dist, current, path = heapq.heappop(pq)

        if current in visited:
            continue

        visited.add(current)

        if current == end:
            return (dist, path)

        for neighbor, weight in graph.get(current, {}).items():
            if neighbor not in visited:
